arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_991820cce6ef4639a5cefcf175cb7872.Models
@using sv_991820cce6ef4639a5cefcf175cb7872.Components.Pages.ApplySteps
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (!_submitted)
    {
        <!-- Step Indicator -->
        <nav class="mb-4">
            <div class="d-flex justify-content-between position-relative">
                @for (int i = 0; i < _stepNames.Length; i++)
                {
                    var step = i;
                    var isCompleted = step < _currentStep;
                    var isCurrent = step == _currentStep;
                    var isFuture = step > _currentStep;

                    <div class="text-center flex-fill" style="z-index: 1;">
                        <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepBadgeClass(step)"
                                style="width: 40px; height: 40px; font-size: 0.85rem;"
                                disabled="@isFuture"
                                @onclick="() => GoToStep(step)">
                            @if (isCompleted)
                            {
                                <span>✓</span>
                            }
                            else
                            {
                                <span>@(step + 1)</span>
                            }
                        </button>
                        <div class="small mt-1 @(isCurrent ? "fw-bold" : "") @(isFuture ? "text-muted" : "")">
                            @_stepNames[step]
                        </div>
                    </div>
                }
            </div>
        </nav>

        <!-- Validation Errors -->
        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
                    @foreach (var error in _errors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        <!-- Step Content -->
        @switch (_currentStep)
        {
            case 0:
                <StepPersonalInfo FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                  FullNameChanged="v => _fullName = v" EmailChanged="v => _email = v"
                                  PhoneChanged="v => _phone = v" AddressChanged="v => _address = v" />
                break;
            case 1:
                <StepWorkHistory Entries="_workEntries" />
                break;
            case 2:
                <StepReferences References="_references" />
                break;
            case 3:
                <StepCoverLetter Text="@_coverLetter" TextChanged="v => _coverLetter = v" MaxLength="2000" />
                break;
            case 4:
                <StepReview Personal="@BuildPersonalInfo()" Work="@BuildWorkHistory()" References="@_references"
                            CoverLetter="@_coverLetter" OnEditSection="GoToStep" Submitting="_submitting" />
                break;
        }

        <!-- Navigation Buttons -->
        <div class="d-flex justify-content-between mt-4">
            <div>
                @if (_currentStep > 0)
                {
                    <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@_submitting">
                        ← Back
                    </button>
                }
            </div>
            <div>
                @if (_currentStep < 4)
                {
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@_validating">
                        @if (_validating)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                            <span>Validating…</span>
                        }
                        else
                        {
                            <span>Next →</span>
                        }
                    </button>
                }
                else
                {
                    <button class="btn btn-success" @onclick="Submit" disabled="@_submitting">
                        @if (_submitting)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                            <span>Submitting…</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                }
            </div>
        </div>
    }
    else
    {
        <!-- Confirmation -->
        <div class="text-center py-5">
            <div class="display-1 text-success mb-3">✓</div>
            <h3>Application Submitted!</h3>
            <p class="lead">Your application ID is <strong>#@_applicationId</strong></p>
