@page "/apply"
@rendermode InteractiveServer
@using sv_991820cce6ef4639a5cefcf175cb7872.Models
@using sv_991820cce6ef4639a5cefcf175cb7872.Components.Pages.ApplySteps
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (!_submitted)
    {
        <!-- Step Indicator -->
        <nav class="mb-4">
            <div class="d-flex justify-content-between position-relative">
                @for (int i = 0; i < _stepNames.Length; i++)
                {
                    var step = i;
                    var isCompleted = step < _currentStep;
                    var isCurrent = step == _currentStep;
                    var isFuture = step > _currentStep;

                    <div class="text-center flex-fill" style="z-index: 1;">
                        <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepBadgeClass(step)"
                                style="width: 40px; height: 40px; font-size: 0.85rem;"
                                disabled="@isFuture"
                                @onclick="() => GoToStep(step)">
                            @if (isCompleted)
                            {
                                <span>✓</span>
                            }
                            else
                            {
                                <span>@(step + 1)</span>
                            }
                        </button>
                        <div class="small mt-1 @(isCurrent ? "fw-bold" : "") @(isFuture ? "text-muted" : "")">
                            @_stepNames[step]
                        </div>
                    </div>
                }
            </div>
        </nav>

        <!-- Validation Errors -->
        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
                    @foreach (var error in _errors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        <!-- Step Content -->
        @switch (_currentStep)
        {
            case 0:
                <StepPersonalInfo FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                  FullNameChanged="v => _fullName = v" EmailChanged="v => _email = v"
                                  PhoneChanged="v => _phone = v" AddressChanged="v => _address = v" />
                break;
            case 1:
                <StepWorkHistory Entries="_workEntries" />
                break;
            case 2:
                <StepReferences References="_references" />
                break;
            case 3:
                <StepCoverLetter Text="@_coverLetter" TextChanged="v => _coverLetter = v" MaxLength="2000" />
                break;
            case 4:
                <StepReview Personal="@BuildPersonalInfo()" Work="@BuildWorkHistory()" References="@_references"
                            CoverLetter="@_coverLetter" OnEditSection="GoToStep" Submitting="_submitting" />
                break;
        }

        <!-- Navigation Buttons -->
        <div class="d-flex justify-content-between mt-4">
            <div>
                @if (_currentStep > 0)
                {
                    <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@_submitting">
                        ← Back
                    </button>
                }
            </div>
            <div>
                @if (_currentStep < 4)
                {
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@_validating">
                        @if (_validating)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                            <span>Validating…</span>
                        }
                        else
                        {
                            <span>Next →</span>
                        }
                    </button>
                }
                else
                {
                    <button class="btn btn-success" @onclick="Submit" disabled="@_submitting">
                        @if (_submitting)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                            <span>Submitting…</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                }
            </div>
        </div>
    }
    else
    {
        <!-- Confirmation -->
        <div class="text-center py-5">
            <div class="display-1 text-success mb-3">✓</div>
            <h3>Application Submitted!</h3>
            <p class="lead">Your application ID is <strong>#@_applicationId</strong></p>
            <p class="text-muted">We'll review your application and get back to you at <strong>@_email</strong>.</p>
            <a href="/apply" class="btn btn-outline-primary mt-3">Submit Another Application</a>
        </div>
    }
</div>

@code {
    private static readonly string[] _stepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep;
    private List<string> _errors = [];
    private bool _validating;
    private bool _submitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3 state
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4 state
    private string _coverLetter = "";

    private string StepBadgeClass(int step) => step switch
    {
        _ when step < _currentStep => "btn-success text-white",
        _ when step == _currentStep => "btn-primary text-white",
        _ => "btn-outline-secondary"
    };

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _errors.Clear();
            _currentStep = step;
        }
    }

    private void PreviousStep()
    {
        _errors.Clear();
        if (_currentStep > 0) _currentStep--;
    }

    private async Task NextStep()
    {
        _errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            _validating = true;
            try
            {
                var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                if (!emailValid)
                {
                    _errors.Add("Please enter a valid email address.");
                    return;
                }
            }
            finally
            {
                _validating = false;
            }
        }

        _currentStep++;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName)) _errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(_email)) _errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(_phone)) _errors.Add("Phone number is required.");
                if (string.IsNullOrWhiteSpace(_address)) _errors.Add("Address is required.");
                break;
            case 1:
                for (int i = 0; i < _workEntries.Count; i++)
                {
                    var e = _workEntries[i];
                    var label = $"Position {i + 1}";
                    if (string.IsNullOrWhiteSpace(e.Company)) _errors.Add($"{label}: Company is required.");
                    if (string.IsNullOrWhiteSpace(e.Title)) _errors.Add($"{label}: Job title is required.");
                    if (e.StartDate == default) _errors.Add($"{label}: Start date is required.");
                    if (!e.IsCurrent && e.EndDate == default) _errors.Add($"{label}: End date is required (or mark as current).");
                }
                break;
            case 2:
                for (int i = 0; i < _references.Count; i++)
                {
                    var r = _references[i];
                    var label = $"Reference {i + 1}";
                    if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"{label}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"{label}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"{label}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"{label}: Phone is required.");
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter)) _errors.Add("Cover letter is required.");
                if (_coverLetter.Length > 2000) _errors.Add("Cover letter must be 2000 characters or fewer.");
                break;
        }
        return _errors.Count == 0;
    }

    private async Task Submit()
    {
        _submitting = true;
        try
        {
            var application = new JobApplication(
                BuildPersonalInfo(),
                BuildWorkHistory(),
                _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        finally
        {
            _submitting = false;
        }
    }

    private PersonalInfo BuildPersonalInfo() => new(_fullName, _email, _phone, _address);

    private WorkHistory BuildWorkHistory() => new(
        _workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()
    );

    // Mutable model classes for form binding
    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

